import React, { Component } from 'react';
import moment from 'moment';
import { requestHeaderDELETEWithAuth, requestHeaderGETWithAuth, requestHeaderPOSTWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, getSearchResult, openPageInNewTab, reloadPage, goHome } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import Table from 'react-bootstrap/Table';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { MapContainer, TileLayer, Marker, Popup, useMap } from 'react-leaflet';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import {
    CButton,
    CCard,
    CCardBody,
    CCardGroup,
    CCol,
    CContainer,
    CForm,
    CInput,
    CInputGroup,
    CInputGroupPrepend,
    CInputGroupText,
    CRow,
    CTextarea
  } from '@coreui/react';
import CIcon from '@coreui/icons-react';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';
import { brandSet } from '@coreui/icons';
import MaterialReactTable from 'material-react-table';
import { BACKEND_PRICE_TRACKER_SERVICE_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';

// Fix Leaflet default marker icon issue with webpack
delete L.Icon.Default.prototype._getIconUrl;
const defaultMarkerIcon = new L.Icon({
    iconUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png',
    iconRetinaUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png',
    shadowUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png',
    iconSize: [25, 41],
    iconAnchor: [12, 41],
    popupAnchor: [1, -34],
    shadowSize: [41, 41],
});

const blueLocationIcon = new L.DivIcon({
    html: `<div style="
        width: 18px;
        height: 18px;
        background-color: #4285F4;
        border: 3px solid #fff;
        border-radius: 50%;
        box-shadow: 0 0 0 2px #4285F4, 0 2px 6px rgba(0,0,0,0.3);
        margin-left: -9px;
        margin-top: -9px;
    "></div>`,
    iconSize: [18, 18],
    iconAnchor: [9, 9],
    popupAnchor: [0, -12],
    className: '',
});

const redMarkerIcon = new L.DivIcon({
    html: `<div style="
        width: 18px;
        height: 18px;
        background-color: #E53935;
        border: 3px solid #fff;
        border-radius: 50%;
        box-shadow: 0 0 0 2px #E53935, 0 2px 6px rgba(0,0,0,0.3);
        margin-left: -9px;
        margin-top: -9px;
    "></div>`,
    iconSize: [18, 18],
    iconAnchor: [9, 9],
    popupAnchor: [0, -12],
    className: '',
});

// Helper component to recenter map when location changes
function RecenterMap({ center }) {
    const map = useMap();
    React.useEffect(() => {
        if (center) {
            map.flyTo(center, 15);
        }
    }, [center, map]);
    return null;
}

//default
const FILE_NAME = "Location.js";

//default
const initialState = {
    isLoaded: false,
    loadingModalVisible: false,
    loadingModalState: 0,
    failureModalVisible: false,
    locationListData: [],
    userLocation: null, // [lat, lng] from browser geolocation
};

const tableColumnData = [
    {
        accessorKey: 'id',
        header: 'ID',
        enableEditing: false,
    },
    {
        accessorKey: 'name',
        header: 'Name',
        enableEditing: true,
    },
    {
        accessorKey: 'description',
        header: 'Description',
        enableEditing: true,
    },
    {
        accessorKey: 'latLong',
        header: 'Lat-Long',
        enableEditing: true,
        Cell: ({ renderedCellValue }) => (
            renderedCellValue
                ? <>
                    <a href={`https://www.google.com/maps/search/${renderedCellValue}`} target="_blank" rel="noopener noreferrer">{renderedCellValue}</a>
                    {' '}
                    <span style={{ cursor: 'pointer' }} onClick={() => { navigator.clipboard.writeText(renderedCellValue); toast('📋 Copied: ' + renderedCellValue); }} title="Copy to clipboard">📋</span>
                </>
                : '—'
        ),
    },
    {
        accessorKey: 'googlePlusCode',
        header: 'Google Plus Code',
        enableEditing: true,
        Cell: ({ renderedCellValue }) => (
            renderedCellValue
                ? <>
                    <a href={`https://www.google.com/maps/place/${encodeURIComponent(renderedCellValue)}`} target="_blank" rel="noopener noreferrer">{renderedCellValue}</a>
                    {' '}
                    <span style={{ cursor: 'pointer' }} onClick={() => { navigator.clipboard.writeText(renderedCellValue); toast('📋 Copied: ' + renderedCellValue); }} title="Copy to clipboard">📋</span>
                </>
                : '—'
        ),
    },
    {
        id: 'directions',
        header: 'Directions',
        enableEditing: false,
        Cell: ({ row }) => (
            row.original.latLong
                ? <a href={`https://www.google.com/maps/dir/?api=1&destination=${row.original.latLong}`} target="_blank" rel="noopener noreferrer" style={{ textDecoration: 'none' }}>🧭 Navigate</a>
                : '—'
        ),
    },
    {
        accessorKey: 'city',
        header: 'city',
        enableEditing: true,
    },
    {
        accessorKey: 'state',
        header: 'state',
        enableEditing: true,
    },
    {
        accessorKey: 'country',
        header: 'country',
        enableEditing: true,
    },
    
    {
        accessorKey: 'createdAt',
        header: 'Created At',
        enableEditing: false,
        Cell: ({ renderedCellValue, row }) => (moment(renderedCellValue).zone('IST').format('YYYY/MM/DD HH:mm:ss ddd'))
    },
    {
        accessorKey: 'updatedAt',
        header: 'Updated At',
        enableEditing: false,
        Cell: ({ renderedCellValue, row }) => (moment(renderedCellValue).zone('IST').format('YYYY/MM/DD HH:mm:ss ddd'))
    },
];


class Location extends Component {

    //default
    constructor(props) {
        super(props);
        this.state = JSON.parse(JSON.stringify(initialState));
    }

    //default
    resetStateToDefault() {
        this.setState(JSON.parse(JSON.stringify(initialState)));
    }

    //default
    reloadData() {
        this.resetStateToDefault();
        this.fetchLocationDataList();
    }

    //default
    componentDidMount() {
        document.title = "Expenses - Location";
        this.fetchLocationDataList();
        this.requestUserLocation();
    }

    requestUserLocation() {
        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(
                (position) => {
                    this.setState({
                        userLocation: [position.coords.latitude, position.coords.longitude],
                        userLocationAccuracy: position.coords.accuracy,
                    });
                },
                (error) => {
                    Logger(FILE_NAME, "requestUserLocation", "", "error", error.message);
                }
            );
        }
    }

    getMapCenter() {
        if (this.state.userLocation) return this.state.userLocation;
        return [12.987977, 77.6219718]; // default
    }

    fetchLocationDataList() {
        let API_URL = BACKEND_PRICE_TRACKER_SERVICE_BASE_URL + '/location/list?offset=0&from=admin-portal';
        const userData = getUserDataFromLocalStorage();

        fetch(API_URL, requestHeaderGETWithAuth(userData.authToken))
        .then(response => {
            if(response.status === 200)
                return response.json();
            if(response.status === 401) {
                this.setState({
                    loadingModalVisible: false,
                    loadingModalState: 0,
                    failureModalVisible: true
                });
                setTimeout(() => {
                    logoutProcedureForLocalStorage();
                    reloadPage();
                }, 500);
            } else {
                this.setState({
                    loadingModalVisible: false,
                    loadingModalState: 0,
                    failureModalVisible: true
                });
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(
            (result) => {
                Logger(FILE_NAME, "fetchLocationDataList", "FETCH_1", "result", result);
                if(result.code === 1001) {
                    //success
                    this.setState({
                        isLoaded: true,
                        locationListData: result.data
                    });
                } else {
                    //something horrible happened
                    this.setState({
                        loadingModalVisible: false,
                        loadingModalState: 0,
                        failureModalVisible: true
                    });
                }
            },
            (error) => {
                Logger(FILE_NAME, "fetchLocationDataList", "FETCH_1", "error", error);
                this.setState({
                    loadingModalVisible: false,
                    loadingModalState: 0,
                    failureModalVisible: true
                });
            }
        );
    }

    submitCreateLocationForm = (event) => {
        event.preventDefault();
        
        let reqData = {
            name: event.target.inputName.value,
            description: event.target.inputDescription.value,
            latLong: event.target.inputLatLong.value,
            googlePlusCode: event.target.inputGooglePlusCode.value,
            city: event.target.inputCity.value,
            state: event.target.inputState.value,
            country: event.target.inputCountry.value
        };

        this.setState({
            loadingModalVisible: true,
            loadingModalState: 0
        });

        this.callCreateLocationApi(reqData);
    }

    //todo: - arsh - https://igod.gov.in/sg/district/states
    callCreateLocationApi(newLocation) {
        let API_URL = BACKEND_PRICE_TRACKER_SERVICE_BASE_URL + '/location/save?offset=0&from=admin-portal';
        const userData = getUserDataFromLocalStorage();
        fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(newLocation), userData.authToken))
        .then(response => {
            if(response.status === 200)
                return response.json();
            if(response.status === 401) {
                this.setState({
                    loadingModalVisible: false,
                    loadingModalState: 0,
                    failureModalVisible: true
                });
                setTimeout(() => {
                    logoutProcedureForLocalStorage();
                    reloadPage();
                }, 500);
            } else {
                this.setState({
                    loadingModalVisible: false,
                    loadingModalState: 0,
                    failureModalVisible: true
                });
            }
            throw new Error("HTTP status is " + response.status);
        })
        .then(
            (result) => {
                Logger(FILE_NAME, "callCreateLocationApi", "FETCH_1", "result", result);
                if(result.code === 1001) {
                    //success
                    this.setState({
                        loadingModalState: 1,
                    });
                    setTimeout(() => {this.reloadData();}, 200);
                } else {
                    //something horrible happened
                    this.setState({
                        loadingModalVisible: false,
                        loadingModalState: 0,
                        failureModalVisible: true
                    });
                }
            },
            (error) => {
                Logger(FILE_NAME, "callCreateLocationApi", "FETCH_1", "error", error);
                this.setState({
                    loadingModalVisible: false,
                    loadingModalState: 0,
                    failureModalVisible: true
                });
            }
        );
    }

    //default
    render() {
        //default
        Logger(FILE_NAME, "render", "", "this.state", this.state);

        return (
            this.state.isLoaded ? 
            <div>
                <h1>LOCATION &nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 
                    <CButton color="success" className="px-4" onClick={() => this.reloadData()}>Reload Data</CButton>
                </h1>
                <br />

                {
                this.state.isLoaded ?
                    <MaterialReactTable
                        initialState={{ density: 'compact' }}
                        columns={tableColumnData} 
                        data={this.state.locationListData}
                        enablePagination = {true}

                        editingMode={"row"}
                        enableEditing
                        onEditingRowSave={(exitEditingMode) => this.handleSaveRowEdits(exitEditingMode)}
                    /> : <br/>
                }

<br /><br />

                {/* Create new location */}
                <CContainer>
                    <CRow className="justify-content-center">
                    <CCol md="8">
                        <CCardGroup>
                        <CCard className="p-4">
                            <CCardBody>
                            <CForm onSubmit={this.submitCreateLocationForm}>
                                <h1>Save a new Location</h1>
                                <CInputGroup className="mb-3">
                                    <CInputGroupPrepend>
                                        <CInputGroupText>
                                        <CIcon name="cilPencil" />
                                        </CInputGroupText>
                                    </CInputGroupPrepend>
                                    <CInput
                                        placeholder="Location Name" 
                                        autoComplete="on"
                                        type="text"
                                        step="any"
                                        id="inputName"
                                        label="Location Name"
                                        required
                                    />
                                </CInputGroup>

                                <CInputGroup className="mb-3">
                                    <CInputGroupPrepend>
                                        <CInputGroupText>
                                        <CIcon name="cilPencil" />
                                        </CInputGroupText>
                                    </CInputGroupPrepend>
                                    <CInput
                                        placeholder="Location Description" 
                                        autoComplete="on"
                                        type="text"
                                        step="any"
                                        id="inputDescription"
                                        label="Location Description"
                                        required
                                    />
                                </CInputGroup>

                                <CInputGroup className="mb-3">
                                    <CInputGroupPrepend>
                                        <CInputGroupText>
                                        <CIcon name="cilPencil" />
                                        </CInputGroupText>
                                    </CInputGroupPrepend>
                                    <CInput
                                        placeholder="LatLong" 
                                        autoComplete="on"
                                        type="text"
                                        step="any"
                                        id="inputLatLong"
                                        label="LatLong"
                                        required
                                    />
                                </CInputGroup>

                                <CInputGroup className="mb-3">
                                    <CInputGroupPrepend>
                                        <CInputGroupText>
                                        <CIcon name="cilPencil" />
                                        </CInputGroupText>
                                    </CInputGroupPrepend>
                                    <CInput
                                        placeholder="Google Plus Code" 
                                        autoComplete="on"
                                        type="text"
                                        step="any"
                                        id="inputGooglePlusCode"
                                        label="Google Plus Code"
                                        required
                                    />
                                </CInputGroup>

                                <CInputGroup className="mb-3">
                                    <CInputGroupPrepend>
                                        <CInputGroupText>
                                        <CIcon name="cilPencil" />
                                        </CInputGroupText>
                                    </CInputGroupPrepend>
                                    <CInput
                                        placeholder="city" 
                                        autoComplete="on"
                                        type="text"
                                        step="any"
                                        id="inputCity"
                                        label="city"
                                        required
                                    />
                                </CInputGroup>

                                <CInputGroup className="mb-3">
                                    <CInputGroupPrepend>
                                        <CInputGroupText>
                                        <CIcon name="cilPencil" />
                                        </CInputGroupText>
                                    </CInputGroupPrepend>
                                    <CInput
                                        placeholder="state" 
                                        autoComplete="on"
                                        type="text"
                                        step="any"
                                        id="inputState"
                                        label="state"
                                        required
                                    />
                                </CInputGroup>

                                <CInputGroup className="mb-3">
                                    <CInputGroupPrepend>
                                        <CInputGroupText>
                                        <CIcon name="cilPencil" />
                                        </CInputGroupText>
                                    </CInputGroupPrepend>
                                    <CInput
                                        placeholder="country" 
                                        autoComplete="on"
                                        type="text"
                                        step="any"
                                        id="inputCountry"
                                        label="country"
                                        required
                                    />
                                </CInputGroup>

                                <CRow>
                                    <CCol xs="6">
                                        <CButton color="success" className="px-4" type='submit'>SAVE</CButton>
                                    </CCol>
                                    <CCol xs="6" className="text-right">
                                        <CButton color="danger" className="px-0" onClick={() => this.reloadData()}>&nbsp;Reset values&nbsp;</CButton>
                                    </CCol>
                                </CRow>
                            </CForm>
                            </CCardBody>
                        </CCard>
                        </CCardGroup>
                    </CCol>
                    </CRow>
                    </CContainer>

<br /><br />

                {/* OpenStreetMap showing all locations */}
                {this.state.locationListData.length > 0 && (
                    <div style={{ marginBottom: '24px' }}>
                        <h3>📍 All Locations on Map &nbsp;
                            <button
                                onClick={() => this.requestUserLocation()}
                                title="Refresh My Location"
                                style={{
                                    width: '32px',
                                    height: '32px',
                                    borderRadius: '50%',
                                    border: 'none',
                                    backgroundColor: '#4285F4',
                                    boxShadow: '0 2px 6px rgba(0,0,0,0.3)',
                                    cursor: 'pointer',
                                    display: 'inline-flex',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    verticalAlign: 'middle',
                                }}
                            >
                                <div style={{
                                    width: '12px',
                                    height: '12px',
                                    backgroundColor: '#fff',
                                    borderRadius: '50%',
                                    border: '2px solid #4285F4',
                                    boxShadow: '0 0 0 2px #fff',
                                }}></div>
                            </button>
                        </h3>
                        <MapContainer
                            center={this.getMapCenter()}
                            zoom={15}
                            style={{ height: '600px', width: '100%', borderRadius: '8px', border: '1px solid #ddd' }}
                        >
                            <TileLayer
                                attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
                                url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                            />
                            <RecenterMap center={this.getMapCenter()} />
                            {this.state.userLocation && (
                                <Marker position={this.state.userLocation} icon={blueLocationIcon}>
                                    <Popup><strong>You are here</strong></Popup>
                                </Marker>
                            )}
                            {!this.state.userLocation && (
                                <Marker position={[12.987977, 77.6219718]} icon={redMarkerIcon}>
                                    <Popup><strong>Default Location</strong></Popup>
                                </Marker>
                            )}
                            {this.state.locationListData
                                .filter(loc => loc.latLong)
                                .map(loc => {
                                    const [lat, lng] = loc.latLong.split(',').map(Number);
                                    if (isNaN(lat) || isNaN(lng)) return null;
                                    return (
                                        <Marker key={loc.id} position={[lat, lng]} icon={defaultMarkerIcon}>
                                            <Popup>
                                                <strong>{loc.name}</strong>
                                                {loc.description && <><br />{loc.description}</>}
                                                {loc.city && <><br />{loc.city}, {loc.state}</>}
                                            </Popup>
                                        </Marker>
                                    );
                                })
                            }
                        </MapContainer>
                    </div>
                )}
                    

                {/* User location info */}
                {this.state.userLocation && (
                    <div style={{ marginTop: '24px', padding: '16px', backgroundColor: '#f0f8ff', borderRadius: '8px', border: '1px solid #cce5ff' }}>
                        <h4>📡 Your Current Location</h4>
                        <p style={{ margin: '4px 0' }}><strong>Latitude:</strong> {this.state.userLocation[0]}</p>
                        <p style={{ margin: '4px 0' }}><strong>Longitude:</strong> {this.state.userLocation[1]}</p>
                        <p style={{ margin: '4px 0' }}><strong>Accuracy:</strong> ±{Math.round(this.state.userLocationAccuracy)} meters</p>
                        <p style={{ margin: '4px 0' }}><strong>Lat,Long:</strong> {this.state.userLocation[0]},{this.state.userLocation[1]}
                            {' '}
                            <span style={{ cursor: 'pointer' }} onClick={() => { navigator.clipboard.writeText(this.state.userLocation[0] + ',' + this.state.userLocation[1]); toast('📋 Copied coordinates'); }} title="Copy">📋</span>
                            {' '}
                            <a href={`https://www.google.com/maps/search/${this.state.userLocation[0]},${this.state.userLocation[1]}`} target="_blank" rel="noopener noreferrer">Open in Google Maps ↗</a>
                        </p>
                    </div>
                )}

                {/* //default */}
                <StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
                <FailureModal visible={this.state.failureModalVisible} />
                <ToastContainer position="bottom-center" autoClose={1000} hideProgressBar newestOnTop closeOnClick theme="light" />
            </div>
            : <Loading />
        );
    }
}

export default Location;
